import { aseet_suppliers } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    supplierdeletion: Boolean,
    supplierItem: Object
  },
  data() {
    return {
      loading: false
    };
  },
  watch: {
    supplierdeletion: {
      async handler() {},
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    async delete_mutation() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(aseet_suppliers, {
          input: {
            action_type: "DELETE_SUPPLIER",
            suppliers_id: this.supplierItem.suppliers_id,
            user_email_id: data.user.user_email_id
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.aseet_suppliers);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    }
  }
};
